using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using Microsoft.Win32;

namespace AkilliKisayol {
 public sealed class StepEditor:Window {
  readonly Dictionary<string,StackPanel> fieldRows=new Dictionary<string,StackPanel>();readonly ActionStep original;readonly ComboBox kind=new ComboBox(),button=new ComboBox();readonly Dictionary<string,TextBox> fields=new Dictionary<string,TextBox>();readonly CheckBox horizontal=new CheckBox{Content="Scroll horizontally"},scale=new CheckBox{Content="Resize window position proportionally when size changes"},altgr=new CheckBox{Content="AltGr"};readonly TextBlock feedback=Theme.Text("",12,"Muted");readonly StackPanel pointer=new StackPanel(),keys=new StackPanel(),delay=new StackPanel(),text=new StackPanel(),app=new StackPanel();
  public ActionStep Result;
  public StepEditor(ActionStep previous=null){
   original=(previous??new ActionStep{Kind="Wait",Delay=250,WindowWidth=1280,WindowHeight=720,X=100,Y=100,X2=200,Y2=100,ScaleWithWindow=true}).Copy();Style=(Style)Application.Current.FindResource(typeof(Window));Title="Edit Macro Step";Width=730;Height=780;MinWidth=620;MinHeight=500;WindowStartupLocation=WindowStartupLocation.CenterOwner;Brand.Fit(this);
   var dock=new DockPanel{Margin=new Thickness(24)};Content=dock;var footer=new StackPanel();footer.Children.Add(feedback);var buttons=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,12,0,0)};buttons.Children.Add(Theme.Button("Cancel",()=>DialogResult=false));buttons.Children.Add(Theme.Button("Apply step",Commit,true));footer.Children.Add(buttons);DockPanel.SetDock(footer,Dock.Bottom);dock.Children.Add(footer);var form=new StackPanel();dock.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});form.Children.Add(Theme.Text("Edit your step as you like",24));
   kind.ItemsSource=new[]{"Key","Text","Wait","Mouse click","Mouse drag","Scroll","Click element","Click button","Focus","Open application","Open content","PowerShell","Terminal (cmd)"};kind.SelectedItem=original.Kind;form.Children.Add(kind);
   Field(app,"AppPath","Target application .exe (leave blank to use previous focus)",original.AppPath??"");app.Children.Add(Theme.Button("Select application",()=>{var picker=new OpenFileDialog{Filter="Application (*.exe)|*.exe"};if(picker.ShowDialog(this)==true)fields["AppPath"].Text=picker.FileName;}));Field(app,"WindowTitle","Window title (optional)",original.WindowTitle??"");form.Children.Add(app);
   Field(keys,"Combo","Key or mouse combination",original.Key>0?TriggerSpec.Format(original.Mods,original.Key):"Ctrl+C");altgr.IsChecked=original.AltGr;keys.Children.Add(altgr);form.Children.Add(keys);
   Field(text,"Text","Text, URL, item name, or command",original.Text??"");fields["Text"].AcceptsReturn=true;fields["Text"].Height=105;fields["Text"].TextWrapping=TextWrapping.Wrap;form.Children.Add(text);
   Field(delay,"Delay","Wait (ms, 0–10000)",original.Delay.ToString());form.Children.Add(delay);
   button.ItemsSource=new[]{"Left","Right","Middle","X1 — Back","X2 — Forward"};button.SelectedIndex=original.MouseButton;pointer.Children.Add(Theme.Text("Mouse button",13));pointer.Children.Add(button);horizontal.IsChecked=original.Horizontal;pointer.Children.Add(horizontal);
   var grid=new System.Windows.Controls.Primitives.UniformGrid{Columns=2};foreach(string name in new[]{"X","Y","X2","Y2","WindowWidth","WindowHeight"}){var field=new StackPanel{Margin=new Thickness(0,0,12,0)};double value=name=="X"?original.X:name=="Y"?original.Y:name=="X2"?original.X2:name=="Y2"?original.Y2:name=="WindowWidth"?original.WindowWidth:original.WindowHeight;Field(field,name,name=="X2"?"End X":name=="Y2"?"End Y":name=="WindowWidth"?"Record window width":name=="WindowHeight"?"Record window height":name,value.ToString(CultureInfo.InvariantCulture));grid.Children.Add(field);}pointer.Children.Add(grid);Field(pointer,"ScrollDelta","Shift amount (120 = one step)",(original.ScrollDelta==0?120:original.ScrollDelta).ToString());Field(pointer,"Duration","Press and drag duration (ms, 0–30000)",original.Duration.ToString());Field(pointer,"Mods","Modifiers (Ctrl / Alt / Shift; optional)",original.Mods==0?"":TriggerSpec.Format(original.Mods,65).Substring(0,TriggerSpec.Format(original.Mods,65).Length-2));scale.IsChecked=original.ScaleWithWindow;pointer.Children.Add(scale);pointer.Children.Add(Theme.Text("Locations are aligned to the top-left of the window. Proportional scaling helps in different sizes; check locations in the changed layout.",12,"Muted"));form.Children.Add(pointer);
   var advanced=new StackPanel();Field(advanced,"AutomationId","Accessible object identifier",original.AutomationId??"");Field(advanced,"WindowClass","Window class (optional)",original.WindowClass??"");form.Children.Add(new Expander{Header="Advanced item matching",Content=advanced,Margin=new Thickness(0,12,0,0)});kind.SelectionChanged+=(s,e)=>Refresh();Refresh();
  }
  void Field(Panel panel,string name,string label,string value){var row=new StackPanel();fieldRows[name]=row;panel.Children.Add(row);var title=Theme.Text(label,12,"Muted");title.Margin=new Thickness(0,12,0,5);row.Children.Add(title);var box=new TextBox{Text=value};fields[name]=box;row.Children.Add(box);}
  void Refresh(){string value=kind.SelectedItem as string??"";bool mouse=value.StartsWith("Mouse ")||value=="Scroll";pointer.Visibility=mouse?Visibility.Visible:Visibility.Collapsed;keys.Visibility=value=="Key"?Visibility.Visible:Visibility.Collapsed;delay.Visibility=value=="Wait"?Visibility.Visible:Visibility.Collapsed;text.Visibility=new[]{"Text","Click button","Click element","Open content","Open application","PowerShell","Terminal (cmd)"}.Contains(value)?Visibility.Visible:Visibility.Collapsed;button.Visibility=value=="Scroll"?Visibility.Collapsed:Visibility.Visible;horizontal.Visibility=value=="Scroll"?Visibility.Visible:Visibility.Collapsed;fieldRows["X2"].Visibility=fieldRows["Y2"].Visibility=value=="Mouse drag"?Visibility.Visible:Visibility.Collapsed;fieldRows["ScrollDelta"].Visibility=value=="Scroll"?Visibility.Visible:Visibility.Collapsed;fieldRows["Duration"].Visibility=value=="Scroll"?Visibility.Collapsed:Visibility.Visible;app.Visibility=value=="Wait"||value=="PowerShell"||value=="Terminal (cmd)"?Visibility.Collapsed:Visibility.Visible;}
  double Number(string name){double number;if(!double.TryParse(fields[name].Text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out number)||double.IsNaN(number)||double.IsInfinity(number))throw new ArgumentException(name+" enter a valid number.");return number;}
  int Integer(string name){double value=Number(name);if(value!=Math.Truncate(value)||value<int.MinValue||value>int.MaxValue)throw new ArgumentException(name+" must be a number.");return (int)value;}
  ActionStep Draft(){var result=original.Copy();result.Kind=kind.SelectedItem as string??"";result.AppPath=fields["AppPath"].Text.Trim();result.WindowTitle=fields["WindowTitle"].Text;result.WindowClass=fields["WindowClass"].Text;result.Text=fields["Text"].Text;result.AutomationId=fields["AutomationId"].Text;
   if(result.Kind=="Key"){TriggerSpec gesture;if(!TriggerSpec.TryParse(fields["Combo"].Text,out gesture)||gesture.Prefix!=0)throw new ArgumentException("Write the single key / mouse combination to send.");result.Mods=gesture.Mods;result.Key=gesture.Key;result.AltGr=altgr.IsChecked==true;}
   if(result.Kind=="Wait")result.Delay=Integer("Delay");
   if(result.Kind.StartsWith("Mouse ")||result.Kind=="Scroll"){result.X=Number("X");result.Y=Number("Y");result.X2=Number("X2");result.Y2=Number("Y2");result.WindowWidth=Number("WindowWidth");result.WindowHeight=Number("WindowHeight");result.MouseButton=button.SelectedIndex;result.Duration=Integer("Duration");result.Horizontal=horizontal.IsChecked==true;result.ScaleWithWindow=scale.IsChecked==true;result.ScrollDelta=Integer("ScrollDelta");TriggerSpec mods;if(!TriggerSpec.TryParse((fields["Mods"].Text.Trim().Length>0?fields["Mods"].Text.Trim()+"+":"")+"A",out mods))throw new ArgumentException("Type modifiers like Ctrl+Shift.");result.Mods=mods.Mods;}
   if(result.Kind=="Focus")result.Text="";if(result.Kind=="Wait"||result.Kind=="PowerShell"||result.Kind=="Terminal (cmd)")result.AppPath="";string issue=Rules.Validate(new Binding{Name="Step",Key=119,IsMacro=true,Kind="Workflow",Steps=new List<ActionStep>{result}},new Binding[0]);if(issue!=null)throw new ArgumentException(issue);return result;
  }
  void Commit(){try{Result=Draft();DialogResult=true;}catch(Exception error){feedback.Text=error.Message;}}
  internal ActionStep DraftForTest(){return Draft();}
  internal void FieldForTest(string name,string value){fields[name].Text=value;}
 }
}
